def load_fruits():
    f = open("fruits.csv", "r")
    fruits = f.readlines()
    f.close()
    for i in range(0, len(fruits)):
        fruits[i] = fruits[i].replace("\n", "")
        fruits[i] = fruits[i].split(",")
        for j in range(1, 3):
            fruits[i][j] = int(fruits[i][j])
    return fruits

def total_stock():
    t = 0
    for row in load_fruits():
        t = t + row[2]
    return t

