import os

def add_log(text):
    if os.path.exists("log.txt"):
        f = open("log.txt", "a")
        f.write("\n" + text)
    else:
        f = open("log.txt", "w")
        f.write(text)
    f.close()

def count_lines():
    if not os.path.exists("log.txt"):
        return 0
    f = open("log.txt", "r")
    n = len(f.readlines())
    f.close()
    return n

